(require '[clojure.edn :as edn] '[clojure.string :as str])
(def g (edn/read-string (slurp "/tmp/kimun-planes/grafo-propio/grafo.edn")))
(defn s [x] (str/replace x "kimun." ""))
(println "cli.commands->kernel targets" (frequencies (for [[a b] (:edges g) :when (and (str/includes? a "cli.commands") (str/includes? b ".kernel."))] (s b))))
(println "cli.commands->host" (frequencies (for [[a b] (:edges g) :when (and (str/includes? a "cli.commands") (str/includes? b ".host."))] (s b))))
(println "cli.commands->cli.commands" (for [[a b] (:edges g) :when (and (str/includes? a "cli.commands") (str/includes? b "cli.commands"))] [(s a) (s b)]))
(println "total lines" (reduce + (map :lines (:nodes g))) "defn-public" (reduce + (map :defn-public (:nodes g))))
(println "avg out" (/ (count (:edges g)) 112.0))
(println "edges rule: same ring catch-all" (count (filter (fn [[a b]] (and (not-any? #(str/starts-with? a %) ["kimun.kernel." "kimun.host." "kimun.graph." "kimun.surface.markdown."]) (not-any? #(str/starts-with? b %) ["kimun.kernel." "kimun.host." "kimun.graph." "kimun.surface.markdown."]))) (:edges g))))
(println "surface->surface edges + surface->cli" (count (filter (fn [[a b]] (and (str/includes? a ".surface.") (str/includes? b ".cli."))) (:edges g))))
(println "cli.commands lines" (reduce + (map :lines (filter #(str/includes? (:ns %) "cli.commands") (:nodes g)))))
(println "surface (no markdown) in-edges from cli" (count (filter (fn [[a b]] (and (str/includes? a "cli.") (str/includes? b "surface."))) (:edges g))))
(println "kernel in-degree from outside kernel by target" (sort-by (comp - val) (frequencies (for [[a b] (:edges g) :when (and (str/includes? b ".kernel.") (not (str/includes? a ".kernel."))) ] (s b)))))
